import { GoogleGenAI, Type } from "@google/genai";

const geocodingSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: {
        type: Type.STRING,
        description: 'The original place name from the input list.'
      },
      lat: {
        type: Type.NUMBER,
        description: 'The geographic latitude.'
      },
      lon: {
        type: Type.NUMBER,
        description: 'The geographic longitude.'
      },
    },
    required: ["name", "lat", "lon"],
    description: 'A geocoded location with its latitude and longitude.'
  },
  description: 'A list of geocoded locations.'
};


/**
 * Geocodes a list of place names using the Gemini API.
 * @param placeNames An array of strings representing geographical locations.
 * @returns A promise that resolves to an array of geocoded location objects.
 */
export const geocodePlaces = async (placeNames: string[]): Promise<{ name: string; lat: number; lon: number }[]> => {
  if (placeNames.length === 0) {
    return [];
  }

  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set for Gemini fallback");
  }
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Geocode the following list of place names. For each, provide the latitude and longitude.

    Rules:
    1. The 'name' in your JSON output MUST exactly match the string provided in the list below.
    2. Only return locations you are confident about.
    3. If multiple locations exist for a name, provide the most prominent or likely one given it's for genealogical records.
    4. Ensure coordinates are precise decimal values.

    Places to geocode:
    ${placeNames.join('\n')}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: geocodingSchema,
      },
    });

    const jsonText = response.text?.trim();
    if (!jsonText) {
        console.warn("Gemini API returned an empty response for geocoding.");
        return [];
    }

    try {
        const geocodedData: { name: string; lat: number; lon: number }[] = JSON.parse(jsonText);
        // Filter out any potential hallucinations where name doesn't match input
        const inputSet = new Set(placeNames);
        return geocodedData.filter(item => inputSet.has(item.name));
    } catch(parseError) {
        console.error("Failed to parse JSON response from Gemini:", jsonText, parseError);
        return [];
    }

  } catch (error) {
    console.error("Error geocoding places with Gemini API:", error);
    return []; // Return empty on error to allow fallback to other methods if needed
  }
};

import { geocodeSinglePlace } from './nominatimService.ts';
import { geocodePlaces as geocodeWithGemini } from './geminiService.ts';
import type { ProgressState } from '../types.ts';

const GEMINI_BATCH_SIZE = 50;

// Helper to add delay, respecting Nominatim's usage policy (max 1 req/sec).
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Geocodes places efficiently by using Gemini AI to process large batches first.
 * Any locations that the AI cannot resolve are then processed via Nominatim sequentially.
 * This significantly improves overall processing speed while maintaining high coverage.
 * 
 * @param placeNames An array of place names to geocode.
 * @param onProgress A callback function to report progress updates.
 * @returns A promise that resolves to a list of geocoded locations.
 */
export const geocode = async (
    placeNames: string[],
    onProgress?: (progress: ProgressState) => void
): Promise<{ name: string; lat: number; lon: number }[]> => {
    const totalPlaces = placeNames.length;
    if (totalPlaces === 0) return [];

    if (onProgress) {
        onProgress({ step: 'Initializing AI batch geocoding...', current: 0, total: totalPlaces });
    }

    const allResults: { name: string; lat: number; lon: number }[] = [];

    // 1. Process with Gemini in large batches first for maximum speed.
    const batches: string[][] = [];
    for (let i = 0; i < placeNames.length; i += GEMINI_BATCH_SIZE) {
        batches.push(placeNames.slice(i, i + GEMINI_BATCH_SIZE));
    }

    let processedByAI = 0;
    for (let i = 0; i < batches.length; i++) {
        const batch = batches[i];
        if (onProgress) {
            onProgress({
                step: `AI is geocoding batch ${i + 1}/${batches.length}...`,
                current: processedByAI,
                total: totalPlaces
            });
        }

        try {
            const batchResults = await geocodeWithGemini(batch);
            allResults.push(...batchResults);
        } catch (err) {
            console.error(`AI Batch ${i} failed:`, err);
        }

        processedByAI += batch.length;
    }

    // 2. Identify missing locations that Gemini couldn't geocode.
    const foundNames = new Set(allResults.map(r => r.name));
    const missingNames = placeNames.filter(name => !foundNames.has(name));

    if (missingNames.length > 0) {
        if (onProgress) {
            onProgress({
                step: `AI resolved ${allResults.length}/${totalPlaces}. Falling back to Nominatim for ${missingNames.length} locations...`,
                current: totalPlaces - missingNames.length,
                total: totalPlaces
            });
        }

        // 3. Sequential fallback to Nominatim for the "tricky" ones.
        // We follow the 1 request per second rule here.
        let fallbackCount = 0;
        for (const name of missingNames) {
            // Respect Nominatim rate limits (1 req/sec)
            if (fallbackCount > 0) {
                await delay(1000);
            }

            try {
                const result = await geocodeSinglePlace(name);
                if (result) {
                    allResults.push(result);
                }
            } catch (err) {
                console.error(`Nominatim failed for ${name}:`, err);
            }

            fallbackCount++;
            if (onProgress) {
                onProgress({
                    step: `Nominatim fallback: ${fallbackCount}/${missingNames.length}`,
                    current: (totalPlaces - missingNames.length) + fallbackCount,
                    total: totalPlaces
                });
            }
        }
    }

    if (onProgress) {
        onProgress({ step: "Geocoding complete.", current: totalPlaces, total: totalPlaces });
    }

    // Ensure we don't return duplicates if multiple entries had the same name
    const uniqueResultsMap = new Map<string, { name: string; lat: number; lon: number }>();
    allResults.forEach(r => uniqueResultsMap.set(r.name, r));

    return Array.from(uniqueResultsMap.values());
};
